// MNB HR Identity Mapping for name
// Combines HR firstname, lastname, middlename into identity displayName

String firstName = (String)link.getAttribute("firstname");
String lastName = (String)link.getAttribute("lastname");
String middleName = (String)link.getAttribute("middleName");

if (firstName == null) firstName = "";
if (lastName == null) lastName = "";
if (middleName == null) middleName = "";

// Clean up whitespace
firstName = firstName.trim();
lastName = lastName.trim();
middleName = middleName.trim();

// Remove extra spaces between middle name and last name
if (!middleName.isEmpty() && !lastName.isEmpty()) {
    // Combine names with proper formatting
    if (!middleName.isEmpty()) {
        return firstName + " " + middleName + " " + lastName;
    } else {
        return firstName + " " + lastName;
    }
} else if (!firstName.isEmpty() && !lastName.isEmpty()) {
    return firstName + " " + lastName;
} else if (!firstName.isEmpty()) {
    return firstName;
} else if (!lastName.isEmpty()) {
    return lastName;
}

// If all names are empty, try using fullName attribute
String fullName = (String)link.getAttribute("fullName");
if (fullName != null && !fullName.isEmpty()) {
    return fullName.trim();
}

return null;
